/* FLUENTR — The Path: lesson exercises, tagged unit/lesson.
   Types: mc (multiple choice), fill (complete the sentence), reorder
   (reorder words), translate (PT->EN, lenient match), match (vocabulary
   pairs). lessonEngine.js assembles a session per lesson from its pool.
   `pt` is the short pedagogical "why" shown in Portuguese in the feedback
   panel (see js/core/feedback.js) — English stays the language of the
   phrases/exercises themselves, per the product's PT-explains-EN model. */

window.WL_DATA = window.WL_DATA || {};
window.WL_DATA.lessons = [
  // ============ u1-l1: Introductions & greetings ============
  { id: 'l-001', unit: 'u1', lesson: 'u1-l1', type: 'mc', level: 'A1', category: 'Multiple Choice', question: 'Which is the most natural way to introduce yourself?', options: ['My name is being Guilherme.', "Hi, I'm Guilherme.", 'I am called of Guilherme.'], answer: 1, explanation: '"Hi, I\'m [name]" is the natural, simple way to introduce yourself.', pt: 'Em inglês não se usa gerúndio para dizer o nome ("My name is being") nem a construção "called of" (tradução literal de "me chamo de"). O jeito natural é sempre "Hi, I\'m [nome]" — simples e direto.' },
  { id: 'l-002', unit: 'u1', lesson: 'u1-l1', type: 'fill', level: 'A1', category: 'Complete the sentence', question: 'Nice to _____ you.', options: ['meet', 'know', 'see'], answer: 0, explanation: '"Nice to meet you" is the standard phrase for a first meeting.', pt: '"Nice to meet you" é a expressão fixa para o primeiro encontro com alguém. "Meet" aqui significa "conhecer pela primeira vez" — não confunda com "know" (já conhecer) ou "see" (ver).' },
  { id: 'l-003', unit: 'u1', lesson: 'u1-l1', type: 'reorder', level: 'A1', category: 'Reorder words', question: 'Put the words in order.', words: ['What', 'do', 'you', 'do?'], explanation: '"What do you do?" is how English speakers ask about someone\'s job.', pt: '"What do you do?" é como se pergunta a profissão de alguém em inglês — não existe uma tradução literal boa para "O que você faz?" fora dessa estrutura fixa.' },
  { id: 'l-004', unit: 'u1', lesson: 'u1-l1', type: 'translate', level: 'A1', category: 'Translation', question: 'De onde você é?', accepted: ['Where are you from?'], explanation: 'Standard question to ask where someone is from.', pt: 'Pergunta padrão para saber a origem de alguém. Repare que em inglês a preposição "from" vai no final: "Where are you from?", nunca "From where are you?".' },
  { id: 'l-005', unit: 'u1', lesson: 'u1-l1', type: 'match', level: 'A1', category: 'Vocabulary Match', question: 'Match each greeting to its meaning.', pairs: [
    { term: 'Nice to meet you', meaning: 'Prazer em conhecê-lo' }, { term: "How's it going?", meaning: 'Como vai?' },
    { term: 'Long time no see', meaning: 'Quanto tempo!' }, { term: 'See you later', meaning: 'Até mais tarde' }
  ], pt: 'Frases de saudação são blocos fixos em inglês — decore como expressão inteira, não palavra por palavra.' },

  // ============ u1-l2: Small talk basics ============
  { id: 'l-006', unit: 'u1', lesson: 'u1-l2', type: 'mc', level: 'A2', category: 'Conversation Response', question: 'Someone asks: "How was your weekend?" Natural reply?', options: ['It was good, thanks! Pretty relaxing. You?', 'My weekend was positive in general terms.', 'I prefer not answer.'], answer: 0, explanation: 'A short, friendly answer that returns the question is the natural small-talk pattern.', pt: 'Small talk em inglês é curto e devolve a pergunta. Respostas muito formais ("positive in general terms") ou mal formadas ("I prefer not answer", que falta o "to") soam estranhas nesse contexto.' },
  { id: 'l-007', unit: 'u1', lesson: 'u1-l2', type: 'fill', level: 'A2', category: 'Complete the sentence', question: 'Nice weather today, _____?', options: ["isn't it", "is it", "doesn't it"], answer: 0, explanation: 'A tag question like "isn\'t it?" is very common in small talk.', pt: 'Tag questions ("..., isn\'t it?") são super comuns em conversas informais em inglês para criar conexão — não existe equivalente direto em português, é uma estrutura fixa que se aprende como padrão.' },
  { id: 'l-008', unit: 'u1', lesson: 'u1-l2', type: 'mc', level: 'A2', category: 'Choose the natural sentence', question: 'Which sounds more natural before a call starts?', options: ['Can you hear me at this exact moment?', 'Can you hear me okay?', 'Is my audio functioning?'], answer: 1, explanation: '"Can you hear me okay?" is the simple, natural way to check audio.', pt: 'Frases técnicas demais viram estranhas quando muito formais ("functioning", "at this exact moment"). O inglês falado prefere simples e direto: "Can you hear me okay?".' },
  { id: 'l-009', unit: 'u1', lesson: 'u1-l2', type: 'reorder', level: 'A2', category: 'Reorder words', question: 'Put the words in order.', words: ['So,', 'how', 'have', 'you', 'been?'], explanation: 'A warm, natural way to catch up with someone.', pt: '"How have you been?" usa o Present Perfect porque pergunta sobre o período desde o último encontro até agora — diferente de "How are you?", que é sobre o momento presente.' },
  { id: 'l-010', unit: 'u1', lesson: 'u1-l2', type: 'translate', level: 'A2', category: 'Translation', question: 'Tudo bem com você?', accepted: ['Are you doing okay?', 'How are you doing?'], explanation: 'A friendly, casual way to check in with someone.', pt: 'Forma casual e afetuosa de perguntar "tudo bem?" — mais pessoal que o "How are you?" de manual.' },

  // ============ u2-l1: Asking for help ============
  { id: 'l-011', unit: 'u2', lesson: 'u2-l1', type: 'mc', level: 'B1', category: 'Multiple Choice', question: 'You need help from a colleague. Best opener?', options: ['Help me now.', 'Hey, do you have a sec? I could use a hand with this.', 'I need you to help.'], answer: 1, explanation: 'A casual, respectful opener that leaves room for them to say when they\'re free.', pt: 'Pedir ajuda de forma direta demais ("Help me now", "I need you to help") soa rude em inglês. A opção natural deixa espaço para a pessoa responder quando puder — educado e ainda assim casual.' },
  { id: 'l-012', unit: 'u2', lesson: 'u2-l1', type: 'fill', level: 'B1', category: 'Complete the sentence', question: "I'm not very familiar _____ this part of the system.", options: ['with', 'in', 'to'], answer: 0, explanation: '"Familiar with" is the correct preposition here.', pt: '"Familiar with" é a combinação fixa (collocation) certa. Em português dizemos "familiarizado COM", então aqui a lógica bate — mas memorize o par como bloco único, porque outras collocations não seguem essa mesma preposição.' },
  { id: 'l-013', unit: 'u2', lesson: 'u2-l1', type: 'mc', level: 'B1', category: 'Error Correction', question: 'Find the mistake: "Can you explain me this?"', options: ['It\'s correct', 'Should be: "Can you explain this to me?"', 'Should be: "Can explain you this?"'], answer: 1, explanation: '"Explain" needs "to" before the person: "explain [thing] to [person]."', pt: '"Explain" nunca vem seguido direto da pessoa — precisa do "to" antes: "explain [algo] TO [pessoa]". É diferente de verbos como "tell", que aceitam objeto direto ("tell me").' },
  { id: 'l-014', unit: 'u2', lesson: 'u2-l1', type: 'reorder', level: 'B1', category: 'Reorder words', question: 'Put the words in order.', words: ['Would', 'you', 'have', 'a', 'minute', 'to', 'help?'], explanation: 'A polite, natural way to ask for someone\'s time.', pt: 'Pedir tempo de alguém com "Would you have a minute..." é mais educado que ir direto ao pedido — muito usado no ambiente de trabalho em inglês.' },
  { id: 'l-015', unit: 'u2', lesson: 'u2-l1', type: 'translate', level: 'B1', category: 'Translation', question: 'Você pode me ajudar com isso quando tiver um tempo?', accepted: ['Could you help me with this when you have a minute?', 'Can you help me with this when you have time?'], explanation: 'A natural, low-pressure way to request help.', pt: '"When you have a minute" tira a pressão do pedido — mostra que não é urgente, o que é visto como educado em inglês profissional.' },

  // ============ u2-l2: Giving quick updates ============
  { id: 'l-016', unit: 'u2', lesson: 'u2-l2', type: 'mc', level: 'B1', category: 'Conversation Response', question: '"Could you give us a quick update?" Best response?', options: ['Yesterday, I worked on resolving some issues and followed up on two tickets.', 'Things happened yesterday.', 'I do not remember.'], answer: 0, explanation: 'A specific, concise summary of concrete work is the natural way to give a status update.', pt: 'Um "update" em inglês profissional é específico e objetivo (o que foi feito, ontem). Respostas vagas ("Things happened") ou evasivas ("I do not remember") não passam a imagem de organização esperada.' },
  { id: 'l-017', unit: 'u2', lesson: 'u2-l2', type: 'fill', level: 'B1', category: 'Complete the sentence', question: "We're currently _____ on the migration.", options: ['working', 'doing', 'making'], answer: 0, explanation: '"Working on [task]" is the natural collocation.', pt: '"Work ON [tarefa]" é a combinação fixa para dizer que está atuando em algo — "do" e "make" não encaixam nessa estrutura.' },
  { id: 'l-018', unit: 'u2', lesson: 'u2-l2', type: 'mc', level: 'B1', category: 'Vocabulary Match', question: 'What does "on track" mean?', options: ['Delayed', 'Progressing as planned', 'Cancelled'], answer: 1, explanation: '"On track" means progressing according to schedule.', pt: '"On track" é uma expressão idiomática que significa "dentro do planejado" — não dá para traduzir palavra por palavra ("na trilha").' },
  { id: 'l-019', unit: 'u2', lesson: 'u2-l2', type: 'reorder', level: 'B1', category: 'Reorder words', question: 'Put the words in order.', words: ["We're", 'about', '70%', 'done.'], explanation: 'A clear, natural way to quantify progress.', pt: 'Forma direta e comum de quantificar progresso em inglês profissional — número + "done" é mais natural que uma frase longa explicando o mesmo.' },
  { id: 'l-020', unit: 'u2', lesson: 'u2-l2', type: 'translate', level: 'B1', category: 'Translation', question: 'Estamos dentro do prazo.', accepted: ["We're on track.", "We're on schedule."], explanation: '"On track" / "on schedule" both express being on time.', pt: '"Dentro do prazo" vira a expressão fixa "on track" ou "on schedule" — nunca tradução literal ("inside the deadline" soaria estranho).' },

  // ============ u3-l1: Joining & giving updates ============
  { id: 'l-021', unit: 'u3', lesson: 'u3-l1', type: 'mc', level: 'B1', category: 'Multiple Choice', question: 'You join a call a few minutes late. What should you say?', options: ['I am here now, continue.', "Sorry I'm late, please continue — I'll catch up.", 'Why did you start without me?'], answer: 1, explanation: 'A brief apology plus a signal to continue keeps the meeting moving.', pt: 'Um pedido de desculpas curto seguido de um sinal para continuar ("please continue") mantém a reunião fluindo — reclamar ("Why did you start without me?") soa deselegante.' },
  { id: 'l-022', unit: 'u3', lesson: 'u3-l1', type: 'fill', level: 'B1', category: 'Complete the sentence', question: 'Can everyone hear me _____?', options: ['okay', 'good', 'correctly'], answer: 0, explanation: '"Can everyone hear me okay?" is the standard way to check audio.', pt: 'Frase padrão para checar áudio em chamadas — "okay" aqui funciona como advérbio informal, mais natural que "good" ou "correctly" nesse contexto.' },
  { id: 'l-023', unit: 'u3', lesson: 'u3-l1', type: 'mc', level: 'B1', category: 'Choose the natural sentence', question: 'Which is more natural to start a meeting?', options: ["Let's begin, shall we?", 'I will now initiate this meeting.', 'The meeting starts this exact moment.'], answer: 0, explanation: '"Let\'s begin, shall we?" is a light, natural way to open a meeting.', pt: '"Shall we?" no final é um jeito leve e educado de abrir uma reunião — frases muito formais ("I will now initiate") soam robóticas no inglês corporativo do dia a dia.' },
  { id: 'l-024', unit: 'u3', lesson: 'u3-l1', type: 'reorder', level: 'B1', category: 'Reorder words', question: 'Put the words in order.', words: ['Could', 'you', 'walk', 'us', 'through', 'that?'], explanation: 'Asks someone to explain something step by step.', pt: '"Walk someone through something" é uma expressão idiomática para "explicar passo a passo" — não existe uma tradução literal boa em português.' },
  { id: 'l-025', unit: 'u3', lesson: 'u3-l1', type: 'translate', level: 'B1', category: 'Translation', question: 'Podemos começar a reunião?', accepted: ['Can we get started?', 'Shall we get started?'], explanation: 'The natural way to open a meeting.', pt: '"Get started" é o phrasal verb natural para "começar" no contexto de reunião — mais usado que o verbo "begin" sozinho aqui.' },

  // ============ u3-l2: Disagreeing & closing politely ============
  { id: 'l-026', unit: 'u3', lesson: 'u3-l2', type: 'mc', level: 'B2', category: 'Multiple Choice', question: 'You disagree with a colleague. Most professional opening?', options: ["That's wrong.", 'I see your point, but I have a slightly different take.', 'No, that will not work.'], answer: 1, explanation: 'Acknowledging their view before offering a different perspective softens disagreement.', pt: 'Discordar em inglês profissional geralmente começa reconhecendo o ponto do outro antes de apresentar uma visão diferente — isso suaviza o discurso e evita soar agressivo ("That\'s wrong").' },
  { id: 'l-027', unit: 'u3', lesson: 'u3-l2', type: 'fill', level: 'B2', category: 'Complete the sentence', question: "I'm not _____ sure that will scale.", options: ['entirely', 'total', 'much'], answer: 0, explanation: '"Not entirely sure" is a softened, polite way to express doubt.', pt: '"Not entirely sure" suaviza a dúvida — é mais natural que "not much sure" (que nem é gramatical) ou "not total sure".' },
  { id: 'l-028', unit: 'u3', lesson: 'u3-l2', type: 'mc', level: 'B1', category: 'Multiple Choice', question: 'What\'s a natural way to end a meeting?', options: ['The meeting is now terminated.', "Let's wrap up — thanks everyone!", 'Stop the meeting now.'], answer: 1, explanation: '"Wrap up" is the natural phrasal verb for ending a meeting.', pt: '"Wrap up" é o phrasal verb natural para "encerrar" — "terminated" soa formal e frio demais, quase burocrático, para uma reunião de equipe.' },
  { id: 'l-029', unit: 'u3', lesson: 'u3-l2', type: 'reorder', level: 'B1', category: 'Reorder words', question: 'Put the words in order.', words: ['Does', 'anyone', 'have', 'questions', 'before', 'we', 'close?'], explanation: 'A polite way to check for final questions before ending.', pt: 'Forma educada de checar se falta alguma dúvida antes de encerrar — comum em qualquer reunião profissional em inglês.' },
  { id: 'l-030', unit: 'u3', lesson: 'u3-l2', type: 'translate', level: 'B2', category: 'Translation', question: 'Eu tenho uma opinião um pouco diferente sobre isso.', accepted: ['I have a slightly different opinion on this.', 'I have a bit of a different take on this.'], explanation: 'A natural, softened way to disagree.', pt: '"Slightly different" suaviza a discordância — evita soar como uma oposição direta ao que foi dito.' },

  // ============ u4-l1: Professional emails ============
  { id: 'l-031', unit: 'u4', lesson: 'u4-l1', type: 'mc', level: 'B1', category: 'Multiple Choice', question: 'Most appropriate email opening to someone you don\'t know well?', options: ['Hey!', 'Hi [Name], I hope this email finds you well.', 'To whoever reads this,'], answer: 1, explanation: 'A friendly-professional opening common in modern business emails.', pt: '"I hope this email finds you well" é uma abertura padrão em e-mails profissionais em inglês — nem informal demais ("Hey!") nem impessoal ("To whoever reads this").' },
  { id: 'l-032', unit: 'u4', lesson: 'u4-l1', type: 'mc', level: 'B2', category: 'Choose the natural sentence', question: 'More polite way to request something urgently?', options: ['I need this today.', 'Would it be possible to have this by end of day?', 'Do this now.'], answer: 1, explanation: 'Softened requests sound more professional than blunt demands.', pt: 'Pedidos diretos ("I need this today", "Do this now") soam mandões em inglês escrito. "Would it be possible..." é a forma educada e ainda assim clara de pedir algo com urgência.' },
  { id: 'l-033', unit: 'u4', lesson: 'u4-l1', type: 'fill', level: 'B1', category: 'Complete the sentence', question: 'Please let me know if you have any _____.', options: ['questions', 'doubts', 'confusions'], answer: 0, explanation: '"Questions" is natural — "doubts" implies distrust in English.', pt: 'Pegadinha clássica: "doubt" existe em inglês, mas soa como desconfiança ou dúvida existencial, não uma simples pergunta. Para "dúvida" no sentido de pergunta, use "question".' },
  { id: 'l-034', unit: 'u4', lesson: 'u4-l1', type: 'reorder', level: 'B1', category: 'Reorder words', question: 'Put the words in order.', words: ['Looking', 'forward', 'to', 'hearing', 'from', 'you.'], explanation: 'A standard, friendly closing line for an email.', pt: 'Fechamento padrão e cordial de e-mail profissional — praticamente uma fórmula fixa, usada em quase todo e-mail de trabalho.' },
  { id: 'l-035', unit: 'u4', lesson: 'u4-l1', type: 'translate', level: 'B1', category: 'Translation', question: 'Segue em anexo o relatório solicitado.', accepted: ['Please find the requested report attached.', 'Please find attached the requested report.'], explanation: '"Please find attached..." is the standard business-email phrase.', pt: '"Please find attached..." é a fórmula fixa para dizer "segue em anexo" em inglês de negócios — não tente traduzir "segue" ao pé da letra.' },

  // ============ u4-l2: Instant messages ============
  { id: 'l-036', unit: 'u4', lesson: 'u4-l2', type: 'mc', level: 'B1', category: 'Multiple Choice', question: 'On Slack/Teams, most appropriate message for a quick question?', options: ['URGENT!!! ANSWER NOW!!!', 'Hey, quick question when you have a sec —', 'I demand an answer.'], answer: 1, explanation: 'A casual, respectful tone works best for instant messages.', pt: 'Mensagens em CAPS LOCK ou tom de ordem soam agressivas em qualquer chat de trabalho em inglês — o tom casual e educado é o padrão esperado em Slack/Teams.' },
  { id: 'l-037', unit: 'u4', lesson: 'u4-l2', type: 'fill', level: 'A2', category: 'Complete the sentence', question: 'No rush, just following _____ on this.', options: ['up', 'on', 'through'], answer: 0, explanation: '"Following up" means checking on the status of something.', pt: '"Follow UP on something" significa "dar continuidade / cobrar retorno sobre algo" — é phrasal verb, não dá para trocar "up" por "on" ou "through".' },
  { id: 'l-038', unit: 'u4', lesson: 'u4-l2', type: 'mc', level: 'B1', category: 'Vocabulary Match', question: 'What does "EOD" commonly mean?', options: ['End of Discussion', 'End of Day', 'Every Other Day'], answer: 1, explanation: '"EOD" (End of Day) is a common abbreviation for deadlines.', pt: '"EOD" (End of Day) é uma sigla extremamente comum em ambientes de trabalho em inglês para prazos — vale memorizar como vocabulário fixo.' },
  { id: 'l-039', unit: 'u4', lesson: 'u4-l2', type: 'reorder', level: 'A2', category: 'Reorder words', question: 'Put the words in order.', words: ['Sure,', "I'll", 'take', 'a', 'look', 'now.'], explanation: 'A short, natural way to confirm you\'ll check something right away.', pt: '"Take a look" é o jeito natural de dizer "dar uma olhada" — resposta curta confirmando ação imediata, comum em mensagens rápidas.' },
  { id: 'l-040', unit: 'u4', lesson: 'u4-l2', type: 'translate', level: 'A2', category: 'Translation', question: 'Você pode me dar um retorno até amanhã?', accepted: ['Can you get back to me by tomorrow?', 'Could you get back to me by tomorrow?'], explanation: '"Get back to me" means to reply or respond.', pt: '"Get back to me" significa "me dar um retorno / responder" — não confundir com "return", que soa estranho nesse contexto.' },

  // ============ u5-l1: Explaining delays ============
  { id: 'l-041', unit: 'u5', lesson: 'u5-l1', type: 'mc', level: 'B1', category: 'Multiple Choice', question: 'You need to explain a delay. Best structure?', options: ['Just say sorry, nothing else.', 'Explain the cause, the impact, and the current status.', 'Blame someone else.'], answer: 1, explanation: 'Cause + impact + status is what people actually want to know about a delay.', pt: 'Ao explicar um atraso, o inglês profissional espera causa + impacto + status atual — só pedir desculpas ou culpar alguém não passa a informação que as pessoas realmente precisam.' },
  { id: 'l-042', unit: 'u5', lesson: 'u5-l1', type: 'fill', level: 'B1', category: 'Complete the sentence', question: "We're a bit _____ schedule this week.", options: ['behind', 'back', 'late of'], answer: 0, explanation: '"Behind schedule" is the standard expression for a late timeline.', pt: '"Behind schedule" é a expressão fixa para "atrasado em relação ao cronograma" — "back" e "late of" não são usados dessa forma.' },
  { id: 'l-043', unit: 'u5', lesson: 'u5-l1', type: 'mc', level: 'B1', category: 'Vocabulary Match', question: 'What does "a bottleneck" mean in project talk?', options: ['A finished task', 'A point that slows down the whole process', 'A type of contract'], answer: 1, explanation: 'A "bottleneck" restricts the flow of a process, causing delays.', pt: '"Bottleneck" (gargalo) é usado em português também, mas em inglês é uma metáfora bem viva no vocabulário de projetos — o ponto que trava todo o fluxo.' },
  { id: 'l-044', unit: 'u5', lesson: 'u5-l1', type: 'reorder', level: 'B1', category: 'Reorder words', question: 'Put the words in order.', words: ['We', 'ran', 'into', 'an', 'unexpected', 'issue.'], explanation: '"Run into an issue" means to unexpectedly encounter a problem.', pt: '"Run into an issue" é a forma natural de dizer "esbarrar em um problema" — uma tradução literal soaria estranha nesse contexto.' },
  { id: 'l-045', unit: 'u5', lesson: 'u5-l1', type: 'translate', level: 'B1', category: 'Translation', question: 'Pedimos desculpas pelo atraso.', accepted: ['We apologize for the delay.', 'Sorry for the delay.'], explanation: 'Standard phrasing for apologizing about a delay.', pt: 'Frase padrão e um pouco mais formal que "Sorry for the delay". Ambas funcionam, mas "we apologize" é mais indicada em comunicação escrita/institucional.' },

  // ============ u5-l2: Escalating & disagreeing ============
  { id: 'l-046', unit: 'u5', lesson: 'u5-l2', type: 'mc', level: 'B2', category: 'Multiple Choice', question: 'You need to escalate an issue you can\'t resolve. Best phrasing?', options: ['This is not my problem.', "I think this needs to be escalated to the infra team.", 'Someone else fix this.'], answer: 1, explanation: '"Escalate" is the natural, professional verb for passing an issue to someone with more authority/expertise.', pt: '"Escalate" é o verbo profissional certo para "encaminhar para um nível acima". Dizer "not my problem" ou "someone else fix this" soa como jogar responsabilidade fora, o que é mal visto.' },
  { id: 'l-047', unit: 'u5', lesson: 'u5-l2', type: 'fill', level: 'B2', category: 'Complete the sentence', question: 'I want to flag a potential _____ with this approach.', options: ['risk', 'danger', 'problematic'], answer: 0, explanation: '"Flag a risk" is the natural professional collocation.', pt: '"Flag a risk" é a expressão usada para "sinalizar um risco" em ambiente corporativo — "danger" é forte demais e "problematic" não funciona como substantivo aqui.' },
  { id: 'l-048', unit: 'u5', lesson: 'u5-l2', type: 'mc', level: 'B2', category: 'Error Correction', question: 'Find the more natural version: "I am not agree with this plan."', options: ['It\'s correct as is', '"I don\'t agree with this plan" is correct', '"I not agree" is correct'], answer: 1, explanation: '"Agree" is a regular verb — the correct form is "I don\'t agree."', pt: '"Agree" é um verbo comum (regular), não se usa com "to be". É o mesmo erro de dizer "eu sou concordo" em vez de "eu concordo" — a forma certa é "I don\'t agree".' },
  { id: 'l-049', unit: 'u5', lesson: 'u5-l2', type: 'reorder', level: 'B2', category: 'Reorder words', question: 'Put the words in order.', words: ['Would', 'it', 'be', 'possible', 'to', 'consider', 'an', 'alternative?'], explanation: 'A softer, indirect way to propose an alternative.', pt: 'Propor uma alternativa de forma indireta ("Would it be possible to...") é mais educado que simplesmente afirmar a ideia — comum em negociações.' },
  { id: 'l-050', unit: 'u5', lesson: 'u5-l2', type: 'translate', level: 'B2', category: 'Translation', question: 'Preciso escalar esse problema para outra equipe.', accepted: ['I need to escalate this issue to another team.'], explanation: '"Escalate to [team]" is the natural professional phrasing.', pt: '"Escalate TO [equipe]" é a estrutura fixa — sempre "to", nunca "for" ou outra preposição.' },

  // ============ u6-l1: Tell me about yourself ============
  { id: 'l-051', unit: 'u6', lesson: 'u6-l1', type: 'mc', level: 'B1', category: 'Multiple Choice', question: 'Best structure for "Tell me about yourself"?', options: ['Talk about your childhood.', 'Present role → past experience → strength → what you want next.', 'List every job you\'ve had.'], answer: 1, explanation: 'This structure keeps the answer focused and relevant to the interviewer.', pt: 'A estrutura ideal para "Tell me about yourself" numa entrevista é: cargo atual → experiência passada → ponto forte → o que busca a seguir. Falar da infância ou listar todos os empregos foge do que o entrevistador quer ouvir.' },
  { id: 'l-052', unit: 'u6', lesson: 'u6-l1', type: 'fill', level: 'B1', category: 'Complete the sentence', question: "I have a strong _____ in problem-solving.", options: ['background', 'past', 'history'], answer: 0, explanation: '"Background in [skill]" is the natural way to describe experience.', pt: '"Background in [área]" é a forma natural de dizer "experiência/formação em" — "past" e "history" não combinam com essa estrutura.' },
  { id: 'l-053', unit: 'u6', lesson: 'u6-l1', type: 'mc', level: 'B2', category: 'Choose the natural sentence', question: 'Which sounds more natural in an interview?', options: ['I are a hard worker person.', "I'm a dedicated professional with a strong work ethic.", 'I work very hard always.'], answer: 1, explanation: 'A more polished, natural way to describe your work ethic.', pt: '"I are" está gramaticalmente errado (deveria ser "I am"), e "I work very hard always" soa como tradução literal com o advérbio no lugar errado. A frase natural usa adjetivos fortes e bem construídos.' },
  { id: 'l-054', unit: 'u6', lesson: 'u6-l1', type: 'reorder', level: 'B1', category: 'Reorder words', question: 'Put the words in order.', words: ["I'm", 'currently', 'looking', 'for', 'a', 'new', 'challenge.'], explanation: 'A natural way to explain why you\'re interviewing.', pt: 'Forma natural e profissional de explicar por que está buscando um novo emprego, sem soar negativo sobre o atual.' },
  { id: 'l-055', unit: 'u6', lesson: 'u6-l1', type: 'translate', level: 'B1', category: 'Translation', question: 'Eu tenho experiência trabalhando sob pressão.', accepted: ['I have experience working under pressure.'], explanation: 'Natural phrasing for describing this common interview strength.', pt: '"Experience + verbo em -ing" é a estrutura certa para descrever vivência prática: "experience working...", não "experience to work...".' },

  // ============ u6-l2: Strengths, weaknesses & goals ============
  { id: 'l-056', unit: 'u6', lesson: 'u6-l2', type: 'mc', level: 'B1', category: 'Conversation Response', question: '"What is your biggest weakness?" Best kind of answer?', options: ['I have no weaknesses.', 'A real but not disqualifying one, plus what you\'re doing about it.', 'Something completely unrelated to work.'], answer: 1, explanation: 'Interviewers want self-awareness and a growth mindset, not a perfect record.', pt: 'Entrevistadores preferem uma fraqueza real, mas não eliminatória, junto com o que você está fazendo para melhorar — dizer que não tem fraquezas soa pouco autêntico.' },
  { id: 'l-057', unit: 'u6', lesson: 'u6-l2', type: 'fill', level: 'B1', category: 'Complete the sentence', question: "I've been actively working _____ improving my public speaking.", options: ['on', 'in', 'for'], answer: 0, explanation: '"Work on [skill]" is the natural collocation for self-improvement.', pt: '"Work ON improving [algo]" é a combinação certa — "in" e "for" não encaixam com "work" nesse sentido.' },
  { id: 'l-058', unit: 'u6', lesson: 'u6-l2', type: 'mc', level: 'B1', category: 'Multiple Choice', question: '"Where do you see yourself in three years?" — best kind of answer?', options: ['I have no idea.', 'A realistic growth path connected to this role.', 'Running my own company in another industry.'], answer: 1, explanation: 'Interviewers want to see ambition that aligns with the role\'s natural growth path.', pt: 'A resposta ideal mostra ambição conectada ao cargo/empresa — respostas sem direção ("I have no idea") ou totalmente fora do contexto passam insegurança ou desalinhamento.' },
  { id: 'l-059', unit: 'u6', lesson: 'u6-l2', type: 'reorder', level: 'B1', category: 'Reorder words', question: 'Put the words in order.', words: ['One', 'of', 'my', 'strengths', 'is', 'staying', 'calm', 'under', 'pressure.'], explanation: 'A natural way to introduce a strength with a concrete quality.', pt: 'Estrutura padrão para apresentar um ponto forte com um exemplo concreto de comportamento, não só um adjetivo solto.' },
  { id: 'l-060', unit: 'u6', lesson: 'u6-l2', type: 'translate', level: 'B1', category: 'Translation', question: 'Eu sou um profissional muito organizado.', accepted: ["I'm a very organized professional.", "I am a highly organized professional."], explanation: 'Natural way to describe this common professional strength.', pt: 'Adjetivo + "professional" é uma forma natural e comum de se descrever em contexto de entrevista/trabalho.' },

  // ============ u7-l1: Service Desk essentials ============
  { id: 'l-061', unit: 'u7', lesson: 'u7-l1', type: 'mc', level: 'A2', category: 'Multiple Choice', question: "User: \"My VPN isn't working.\" Best response?", options: ['Restart.', "Could you tell me what error message you're seeing?", 'Not my problem.'], answer: 1, explanation: 'Asking a clarifying question first leads to a much faster, more accurate fix.', pt: 'Antes de sugerir uma solução, o inglês técnico profissional pede um detalhe do erro primeiro ("what error message") — isso evita perder tempo com soluções genéricas como só "Restart."' },
  { id: 'l-062', unit: 'u7', lesson: 'u7-l1', type: 'fill', level: 'B1', category: 'Complete the sentence', question: "Let's _____ this step by step.", options: ['troubleshoot', 'trouble', 'shoot'], answer: 0, explanation: '"Troubleshoot" is the standard verb for diagnosing a technical problem.', pt: '"Troubleshoot" é o verbo técnico padrão para "diagnosticar/resolver um problema passo a passo" — não existe uma tradução literal de uma palavra só em português.' },
  { id: 'l-063', unit: 'u7', lesson: 'u7-l1', type: 'mc', level: 'B1', category: 'Vocabulary Match', question: 'What does "escalate a ticket" mean?', options: ['Delete the ticket', 'Pass it to a higher support level', 'Close it without a fix'], answer: 1, explanation: 'Escalating means moving an issue to someone with more expertise or authority.', pt: '"Escalate a ticket" significa encaminhar o chamado para um nível de suporte mais especializado — não é o mesmo que fechar ou deletar.' },
  { id: 'l-064', unit: 'u7', lesson: 'u7-l1', type: 'reorder', level: 'A2', category: 'Reorder words', question: 'Put the words in order.', words: ['Have', 'you', 'tried', 'restarting', 'your', 'computer?'], explanation: 'A common, natural first troubleshooting question.', pt: 'Pergunta clássica e universal de troubleshooting em suporte técnico — em inglês essa é a estrutura exata usada, com "Have you tried + gerúndio".' },
  { id: 'l-065', unit: 'u7', lesson: 'u7-l1', type: 'translate', level: 'A2', category: 'Translation', question: 'Qual mensagem de erro você está vendo?', accepted: ['What error message are you seeing?'], explanation: 'A key troubleshooting question for any support conversation.', pt: 'Pergunta-chave de diagnóstico técnico — repare na ordem das palavras: "What error message are you seeing?", não "What message of error..." (calque do português).' },

  // ============ u7-l2: Cloud & incidents ============
  { id: 'l-066', unit: 'u7', lesson: 'u7-l2', type: 'mc', level: 'B1', category: 'Multiple Choice', question: 'How do you announce a service outage to users?', options: ['System broke, sorry.', "We're currently experiencing a service outage.", 'Everything down now.'], answer: 1, explanation: 'A calm, standard phrase for opening incident communication.', pt: 'Comunicar uma falha de forma calma e padronizada ("We\'re currently experiencing...") passa profissionalismo — frases informais demais ("System broke, sorry") soam despreparadas numa comunicação oficial de incidente.' },
  { id: 'l-067', unit: 'u7', lesson: 'u7-l2', type: 'fill', level: 'B1', category: 'Complete the sentence', question: 'We are _____ investigating the root cause.', options: ['actively', 'active', 'action'], answer: 0, explanation: '"Actively investigating" reassures users that work is genuinely in progress.', pt: '"Actively" reforça que o trabalho está realmente em andamento — tranquiliza quem está lendo a atualização do incidente.' },
  { id: 'l-068', unit: 'u7', lesson: 'u7-l2', type: 'mc', level: 'B1', category: 'Vocabulary Match', question: 'What does "downtime" mean?', options: ['Time to relax', 'Time when a system is unavailable', 'The end of a shift'], answer: 1, explanation: '"Downtime" refers to a period when a system is not working/available.', pt: '"Downtime" é o tempo em que um sistema fica indisponível — termo técnico usado universalmente, inclusive já emprestado pelo português técnico.' },
  { id: 'l-069', unit: 'u7', lesson: 'u7-l2', type: 'reorder', level: 'B1', category: 'Reorder words', question: 'Put the words in order.', words: ['A', 'fix', 'has', 'been', 'identified', 'and', 'deployed.'], explanation: 'Standard incident-communication phrasing to announce a resolution step.', pt: 'Estrutura em voz passiva ("has been identified and deployed") é o padrão em comunicações de incidente — foca na ação, não em quem fez.' },
  { id: 'l-070', unit: 'u7', lesson: 'u7-l2', type: 'translate', level: 'B1', category: 'Translation', question: 'O problema foi resolvido.', accepted: ['The issue has been resolved.', 'The problem has been resolved.'], explanation: 'Standard phrase to close out an incident update.', pt: 'Frase fixa para encerrar uma comunicação de incidente — "issue" e "problem" funcionam, mas "issue" é ligeiramente mais comum em contexto técnico.' },

  // ============ u8-l1: Negotiation & deadlines ============
  { id: 'l-071', unit: 'u8', lesson: 'u8-l1', type: 'mc', level: 'B2', category: 'Multiple Choice', question: 'You need to ask for more time. Most professional phrasing?', options: ["I can't finish, sorry.", 'Would it be possible to extend the deadline by two days?', 'Deadline impossible, change it.'], answer: 1, explanation: 'A polite, specific request is the professional way to negotiate a deadline.', pt: 'Pedir prazo de forma educada e específica ("Would it be possible to extend...by two days") é muito mais profissional do que simplesmente dizer que não vai dar tempo ou exigir mudança.' },
  { id: 'l-072', unit: 'u8', lesson: 'u8-l1', type: 'fill', level: 'B2', category: 'Complete the sentence', question: 'Could we meet somewhere in the _____?', options: ['middle', 'center', 'half'], answer: 0, explanation: '"Meet somewhere in the middle" means to compromise during a negotiation.', pt: '"Meet somewhere in the middle" é expressão idiomática para "chegar a um meio-termo" — não existe uma tradução literal boa.' },
  { id: 'l-073', unit: 'u8', lesson: 'u8-l1', type: 'mc', level: 'B2', category: 'Choose the natural sentence', question: 'More professional way to say "I need this today"?', options: ['I need this today.', 'Would it be possible to have this completed by the end of the day?', 'Give me this today.'], answer: 1, explanation: 'The softened version is standard professional phrasing for an urgent request.', pt: 'Mesma lógica de antes: pedidos urgentes soam mais profissionais quando suavizados com "Would it be possible..." em vez de comandos diretos.' },
  { id: 'l-074', unit: 'u8', lesson: 'u8-l1', type: 'reorder', level: 'B2', category: 'Reorder words', question: 'Put the words in order.', words: ['We', 'need', 'to', 'prioritize', 'the', 'most', 'urgent', 'tasks', 'first.'], explanation: '"Prioritize" is the natural verb for ordering tasks by importance.', pt: '"Prioritize" é o verbo certo para "ordenar por importância" — em inglês a estrutura é direta: "prioritize [algo]", sem preposição no meio.' },
  { id: 'l-075', unit: 'u8', lesson: 'u8-l1', type: 'translate', level: 'B2', category: 'Translation', question: 'Precisamos priorizar as tarefas mais urgentes primeiro.', accepted: ['We need to prioritize the most urgent tasks first.'], explanation: 'Natural phrasing for setting priorities.', pt: 'Mesma estrutura do item anterior, agora em tradução — "prioritize" não precisa de preposição antes do objeto.' },

  // ============ u8-l2: Tone & presentations ============
  { id: 'l-076', unit: 'u8', lesson: 'u8-l2', type: 'mc', level: 'B1', category: 'Multiple Choice', question: 'What\'s a natural way to start a presentation?', options: ['Today I will talk you about...', "Today, I'd like to walk you through...", 'I go explain about...'], answer: 1, explanation: '"I\'d like to walk you through..." is a natural, professional way to introduce a topic.', pt: '"I\'d like to walk you through..." é uma abertura natural e profissional. "I go explain about" é calque direto do português ("eu vou explicar sobre"), que não existe em inglês correto.' },
  { id: 'l-077', unit: 'u8', lesson: 'u8-l2', type: 'fill', level: 'B1', category: 'Complete the sentence', question: "Let's move on _____ the next point.", options: ['to', 'for', 'at'], answer: 0, explanation: '"Move on to [something]" is the correct phrasal verb + preposition combination.', pt: '"Move on TO [algo]" é phrasal verb + preposição fixos — não dá para trocar "to" por "for" ou "at".' },
  { id: 'l-078', unit: 'u8', lesson: 'u8-l2', type: 'mc', level: 'B2', category: 'Multiple Choice', question: 'Which message is casual, and which is executive-toned? "Can you send this today?" vs. "Would it be possible to send this over by end of day?"', options: ['Both are casual', 'First is casual, second is more formal/executive', 'Both are equally formal'], answer: 1, explanation: 'Neither is "wrong" — tone should match the audience and context. The second suits a more senior or external recipient.', pt: 'As duas frases estão gramaticalmente corretas — a diferença é de registro (tom). A segunda, mais indireta, soa mais formal/executiva; a primeira é mais casual. Escolher o tom certo para a audiência é tão importante quanto a gramática.' },
  { id: 'l-079', unit: 'u8', lesson: 'u8-l2', type: 'reorder', level: 'B1', category: 'Reorder words', question: 'Put the words in order.', words: ['As', 'you', 'can', 'see', 'on', 'this', 'slide,'], explanation: 'A standard phrase to direct attention to a visual during a presentation.', pt: 'Frase padrão para direcionar a atenção da audiência a um slide durante uma apresentação.' },
  { id: 'l-080', unit: 'u8', lesson: 'u8-l2', type: 'translate', level: 'B1', category: 'Translation', question: 'Vamos passar para o próximo tópico.', accepted: ["Let's move on to the next topic.", "Let's move to the next topic."], explanation: 'The natural transition phrase in presentations.', pt: 'Frase de transição clássica em apresentações — praticamente uma fórmula fixa em inglês de negócios.' },

  // ============ u9-l1: At the airport & hotel ============
  { id: 'l-081', unit: 'u9', lesson: 'u9-l1', type: 'mc', level: 'A2', category: 'Multiple Choice', question: 'At the check-in counter, what\'s the natural way to ask for a window seat?', options: ['Give me window seat.', 'Could I have a window seat, please?', 'I want window seat now.'], answer: 1, explanation: 'Polite request form for travel service situations.', pt: 'Pedidos em contextos de atendimento (check-in, hotel) soam mais naturais com "Could I have...?" — pedir de forma direta ("Give me") soa rude em inglês, mesmo sendo comum em português.' },
  { id: 'l-082', unit: 'u9', lesson: 'u9-l1', type: 'fill', level: 'A2', category: 'Complete the sentence', question: "I'd like to _____ a room for two nights, please.", options: ['book', 'make', 'do'], answer: 0, explanation: '"Book a room" is the standard collocation.', pt: '"Book a room" é a combinação fixa para reservar — "make a room" ou "do a room" não existem em inglês.' },
  { id: 'l-083', unit: 'u9', lesson: 'u9-l1', type: 'reorder', level: 'B1', category: 'Reorder words', question: 'Put the words in order.', words: ['Is', 'breakfast', 'included', 'in', 'the', 'price?'], explanation: 'Common question when checking into a hotel.', pt: 'Pergunta padrão ao fazer check-in em hotel — "included in the price" é a estrutura natural para "incluso no preço".' },
  { id: 'l-084', unit: 'u9', lesson: 'u9-l1', type: 'translate', level: 'A2', category: 'Translation', question: 'Qual é a política de cancelamento?', accepted: ["What's the cancellation policy?", 'What is the cancellation policy?'], explanation: 'Key question before booking anything.', pt: 'Pergunta essencial antes de reservar qualquer coisa — "cancellation policy" é o termo padrão em inglês.' },
  { id: 'l-085', unit: 'u9', lesson: 'u9-l1', type: 'match', level: 'A2', category: 'Vocabulary Match', question: 'Match each travel term to its meaning.', pairs: [
    { term: 'Boarding pass', meaning: 'Cartão de embarque' }, { term: 'Baggage claim', meaning: 'Retirada de bagagem' },
    { term: 'Check-in desk', meaning: 'Balcão de check-in' }, { term: 'Layover', meaning: 'Conexão (escala)' }
  ], pt: 'Vocabulário essencial de aeroporto — decore como blocos fixos, muito usados em placas e anúncios.' },

  // ============ u9-l2: Emergencies & asking for help ============
  { id: 'l-086', unit: 'u9', lesson: 'u9-l2', type: 'mc', level: 'B1', category: 'Multiple Choice', question: "You lost your passport abroad. What's the first thing to say at the embassy?", options: ['I lost passport, help now.', "I've lost my passport — could you help me with the next steps?", 'Passport is gone, fix it.'], answer: 1, explanation: 'A calm, complete sentence gets better help than a fragmented demand.', pt: 'Em uma emergência, frases completas e educadas ("I\'ve lost my passport — could you help me...") geram mais ajuda do que frases fragmentadas e diretas demais, mesmo sob estresse.' },
  { id: 'l-087', unit: 'u9', lesson: 'u9-l2', type: 'fill', level: 'A2', category: 'Complete the sentence', question: 'Call an ambulance, someone is _____!', options: ['hurt', 'hurting', 'hurted'], answer: 0, explanation: '"Hurt" is both the verb and the adjective here — "someone is hurt" describes their state.', pt: '"Hurt" funciona como adjetivo aqui (machucado) — não existe "hurted", já que "hurt" é irregular (hurt-hurt-hurt).' },
  { id: 'l-088', unit: 'u9', lesson: 'u9-l2', type: 'reorder', level: 'B1', category: 'Reorder words', question: 'Put the words in order.', words: ['Where', 'is', 'the', 'nearest', 'hospital?'], explanation: 'Essential emergency question.', pt: 'Pergunta essencial em emergências — "nearest" (mais próximo) é a palavra-chave para localizar ajuda rápido.' },
  { id: 'l-089', unit: 'u9', lesson: 'u9-l2', type: 'translate', level: 'B1', category: 'Translation', question: 'Preciso de ajuda, estou perdido.', accepted: ["I need help, I'm lost.", 'I need help — I am lost.'], explanation: 'Direct, clear way to ask for help when lost.', pt: 'Frase direta e clara para pedir ajuda quando está perdido — simples é melhor em situações de emergência.' },
  { id: 'l-090', unit: 'u9', lesson: 'u9-l2', type: 'match', level: 'A2', category: 'Vocabulary Match', question: 'Match each emergency term to its meaning.', pairs: [
    { term: 'Emergency room', meaning: 'Pronto-socorro' }, { term: 'Lost and found', meaning: 'Achados e perdidos' },
    { term: 'Call the police', meaning: 'Chamar a polícia' }, { term: 'I need a doctor', meaning: 'Preciso de um médico' }
  ], pt: 'Vocabulário de emergência — frases que devem ser reconhecidas instantaneamente, sem precisar traduzir mentalmente.' },

  // ============ Extra bank (3 more per lesson) ============
  // u1-l1
  { id: 'l-091', unit: 'u1', lesson: 'u1-l1', type: 'mc', level: 'A1', category: 'Multiple Choice', question: 'Someone says "This is my colleague, Marina." What do you say?', options: ['Nice to meet you, Marina.', 'I meet you now.', 'Marina, hello of you.'], answer: 0, explanation: '"Nice to meet you, [name]" is the standard response when introduced to someone.', pt: 'Ao ser apresentado a alguém, a resposta padrão é "Nice to meet you, [nome]" — as outras opções são traduções literais que não existem em inglês.' },
  { id: 'l-092', unit: 'u1', lesson: 'u1-l1', type: 'fill', level: 'A1', category: 'Complete the sentence', question: "I'm Guilherme. And you _____?", options: ['are', 'is', 'be'], answer: 0, explanation: '"And you are?" is a common way to ask someone\'s name back.', pt: '"And you are?" com entonação de pergunta é um jeito comum e educado de perguntar o nome de volta — usa "are" porque combina com "you".' },
  { id: 'l-093', unit: 'u1', lesson: 'u1-l1', type: 'reorder', level: 'A1', category: 'Reorder words', question: 'Put the words in order.', words: ['This', 'is', 'my', 'friend,', 'Rayssa.'], explanation: 'The standard structure for introducing someone else.', pt: 'Estrutura padrão para apresentar outra pessoa: "This is my [relação], [nome]" — simples e direta.' },

  // u1-l2
  { id: 'l-094', unit: 'u1', lesson: 'u1-l2', type: 'mc', level: 'A2', category: 'Multiple Choice', question: 'How do you politely end a small-talk conversation?', options: ['I need to go now, bye.', "Well, it was great catching up — I should get going.", 'Stop talking, I have to leave.'], answer: 1, explanation: 'A warm closing line softens the exit instead of ending the conversation abruptly.', pt: 'Encerrar small talk de forma seca ("I need to go now") soa brusco. O natural é suavizar com algo como "it was great catching up" antes de sair.' },
  { id: 'l-095', unit: 'u1', lesson: 'u1-l2', type: 'fill', level: 'A2', category: 'Complete the sentence', question: 'What do you do _____ a living?', options: ['for', 'in', 'with'], answer: 0, explanation: '"What do you do for a living?" is the fixed way to ask about someone\'s job.', pt: '"For a living" é bloco fixo que só combina com "for" — pergunta padrão sobre profissão em conversas informais.' },
  { id: 'l-096', unit: 'u1', lesson: 'u1-l2', type: 'reorder', level: 'A2', category: 'Reorder words', question: 'Put the words in order.', words: ['Any', 'plans', 'for', 'the', 'weekend?'], explanation: 'A common small-talk question to keep a conversation going.', pt: 'Pergunta clássica de small talk para manter a conversa fluindo — muito comum em contextos casuais de trabalho.' },

  // u2-l1
  { id: 'l-097', unit: 'u2', lesson: 'u2-l1', type: 'mc', level: 'B1', category: 'Multiple Choice', question: 'A colleague helped you fix a bug. Best way to thank them?', options: ['Thanks.', "I really appreciate your help with this — saved me a lot of time.", 'OK thanks bye.'], answer: 1, explanation: 'A specific, warm thank-you acknowledges the actual help given.', pt: 'Um agradecimento específico ("saved me a lot of time") soa mais genuíno do que um "Thanks" seco — vale o esforço extra em ambiente de trabalho.' },
  { id: 'l-098', unit: 'u2', lesson: 'u2-l1', type: 'fill', level: 'B1', category: 'Complete the sentence', question: "I'm stuck _____ this bug, could you take a look?", options: ['on', 'in', 'at'], answer: 0, explanation: '"Stuck on [problem]" is the natural collocation.', pt: '"Stuck ON [problema]" é a combinação certa — não "in" nem "at" — para dizer que está travado tentando resolver algo.' },
  { id: 'l-099', unit: 'u2', lesson: 'u2-l1', type: 'reorder', level: 'B1', category: 'Reorder words', question: 'Put the words in order.', words: ['Do', 'you', 'mind', 'giving', 'me', 'a', 'hand?'], explanation: 'A polite, common way to ask for assistance.', pt: '"Do you mind + gerúndio" é uma estrutura educada muito usada para pedir ajuda sem soar como uma ordem.' },

  // u2-l2
  { id: 'l-100', unit: 'u2', lesson: 'u2-l2', type: 'mc', level: 'B1', category: 'Multiple Choice', question: 'Your manager asks for an update and things are NOT going well. Best approach?', options: ['Hide the problem and say everything is fine.', "We hit a blocker — here's what happened and our plan to fix it.", 'It\'s not my fault, don\'t blame me.'], answer: 1, explanation: 'Transparent updates that include a plan build more trust than hiding problems.', pt: 'Em inglês profissional, transparência com um plano de ação ("here\'s what happened and our plan") gera muito mais confiança do que esconder o problema ou só se defender.' },
  { id: 'l-101', unit: 'u2', lesson: 'u2-l2', type: 'fill', level: 'B1', category: 'Complete the sentence', question: "There's been a slight _____ in the timeline.", options: ['delay', 'lateness', 'slowness'], answer: 0, explanation: '"Delay" is the natural noun for a timeline slipping.', pt: '"Delay" é o substantivo natural para "atraso" em cronogramas — "lateness" e "slowness" não combinam com "timeline" dessa forma.' },
  { id: 'l-102', unit: 'u2', lesson: 'u2-l2', type: 'reorder', level: 'B1', category: 'Reorder words', question: 'Put the words in order.', words: ['I', 'should', 'have', 'this', 'wrapped', 'up', 'by', 'Friday.'], explanation: '"Wrap up" here means to finish something.', pt: '"Wrap up" (encerrar/finalizar) combinado com "by [data]" é forma natural de dar um prazo estimado em um update.' },

  // u3-l1
  { id: 'l-103', unit: 'u3', lesson: 'u3-l1', type: 'mc', level: 'B1', category: 'Multiple Choice', question: 'You want to add a point during a meeting. Natural way to jump in?', options: ['Stop, I talk now.', 'Sorry to jump in — can I add something here?', 'Listen to me now.'], answer: 1, explanation: '"Sorry to jump in" is the standard polite way to interrupt in English meetings.', pt: '"Sorry to jump in" é a forma educada e padrão de interromper uma reunião em inglês — interromper diretamente soa rude.' },
  { id: 'l-104', unit: 'u3', lesson: 'u3-l1', type: 'fill', level: 'B1', category: 'Complete the sentence', question: "Let's stay _____ topic, we can discuss that later.", options: ['on', 'in', 'at'], answer: 0, explanation: '"Stay on topic" is the fixed expression for keeping focus.', pt: '"Stay ON topic" é expressão fixa para "manter o foco no assunto" — não varia a preposição.' },
  { id: 'l-105', unit: 'u3', lesson: 'u3-l1', type: 'translate', level: 'B1', category: 'Translation', question: 'Alguém pode compartilhar a tela?', accepted: ['Can someone share their screen?', 'Could someone share their screen?'], explanation: 'Standard request to start screen sharing in a call.', pt: 'Pedido padrão em chamadas de trabalho — "share their screen" é a expressão fixa para "compartilhar a tela".' },

  // u3-l2
  { id: 'l-106', unit: 'u3', lesson: 'u3-l2', type: 'mc', level: 'B2', category: 'Multiple Choice', question: 'Someone keeps interrupting you in a meeting. Polite way to reclaim the floor?', options: ['Shut up, let me finish.', 'If I could just finish this point —', 'You always do this.'], answer: 1, explanation: 'A short, firm-but-polite phrase gets your point back without escalating conflict.', pt: '"If I could just finish this point" é firme sem ser agressivo — recupera a palavra sem gerar conflito, diferente de acusar a pessoa diretamente.' },
  { id: 'l-107', unit: 'u3', lesson: 'u3-l2', type: 'fill', level: 'B2', category: 'Complete the sentence', question: "Let's agree to _____ on this one.", options: ['disagree', 'fight', 'lose'], answer: 0, explanation: '"Agree to disagree" is a fixed idiom for ending a debate respectfully.', pt: '"Agree to disagree" é expressão idiomática fixa para encerrar um debate sem chegar a um consenso, mas de forma respeitosa.' },
  { id: 'l-108', unit: 'u3', lesson: 'u3-l2', type: 'reorder', level: 'B2', category: 'Reorder words', question: 'Put the words in order.', words: ['That\'s', 'a', 'fair', 'point,', 'but', 'consider', 'this.'], explanation: 'Acknowledging a point before countering it is the natural pattern for polite disagreement.', pt: 'Validar o argumento do outro ("That\'s a fair point") antes de contrapor é o padrão de discordância educada em inglês profissional.' },

  // u4-l1
  { id: 'l-109', unit: 'u4', lesson: 'u4-l1', type: 'mc', level: 'B1', category: 'Multiple Choice', question: 'Best way to close a formal email?', options: ['Bye bye!', 'Best regards,', 'See ya.'], answer: 1, explanation: '"Best regards," is the standard formal email closing.', pt: '"Best regards," é o fechamento padrão de e-mail formal em inglês — "Bye bye!" e "See ya" são informais demais para esse contexto.' },
  { id: 'l-110', unit: 'u4', lesson: 'u4-l1', type: 'fill', level: 'B1', category: 'Complete the sentence', question: "I'm writing to _____ you about tomorrow's meeting.", options: ['inform', 'communicate', 'say'], answer: 0, explanation: '"Inform you about" is the natural formal-email collocation.', pt: '"Inform you about" é a combinação natural em e-mail formal — "communicate" pede uma estrutura diferente, e "say" é informal demais.' },
  { id: 'l-111', unit: 'u4', lesson: 'u4-l1', type: 'translate', level: 'B1', category: 'Translation', question: 'Por favor, me avise se precisar de mais alguma informação.', accepted: ['Please let me know if you need any further information.', 'Please let me know if you need more information.'], explanation: 'Standard polite closing offer in professional emails.', pt: 'Frase fixa de fechamento educado em e-mails — "let me know if you need..." é padrão em qualquer comunicação profissional.' },

  // u4-l2
  { id: 'l-112', unit: 'u4', lesson: 'u4-l2', type: 'mc', level: 'A2', category: 'Multiple Choice', question: 'You need to leave a chat conversation abruptly. Natural way to say it?', options: ['Bye, gone.', 'Got pulled into something — will circle back!', 'I disappear now.'], answer: 1, explanation: '"Will circle back" signals you\'ll return without leaving the other person hanging.', pt: '"Circle back" é phrasal verb comum para "retomar depois" — sinaliza que você volta, evitando deixar a pessoa sem resposta.' },
  { id: 'l-113', unit: 'u4', lesson: 'u4-l2', type: 'fill', level: 'A2', category: 'Complete the sentence', question: 'Just a heads _____, the deploy is happening at 3pm.', options: ['up', 'on', 'to'], answer: 0, explanation: '"A heads up" is a fixed noun phrase meaning an early warning.', pt: '"A heads up" é substantivo fixo para "um aviso prévio" — sempre com "up", nunca varia.' },
  { id: 'l-114', unit: 'u4', lesson: 'u4-l2', type: 'reorder', level: 'A2', category: 'Reorder words', question: 'Put the words in order.', words: ['Can', 'we', 'hop', 'on', 'a', 'quick', 'call?'], explanation: '"Hop on a call" is a casual, common way to suggest a quick call.', pt: '"Hop on a call" é uma forma casual e muito comum de propor uma ligação rápida em vez de continuar por texto.' },

  // u5-l1
  { id: 'l-115', unit: 'u5', lesson: 'u5-l1', type: 'mc', level: 'B1', category: 'Multiple Choice', question: 'A delay was caused by a third-party vendor. Natural way to explain it?', options: ['It\'s their fault, not ours.', 'The delay is due to a dependency on a third-party vendor.', 'Vendor bad, we wait.'], answer: 1, explanation: '"Due to a dependency on..." explains the cause professionally without pointing fingers.', pt: '"Due to a dependency on..." explica a causa de forma profissional sem soar como estar jogando a culpa em outra empresa.' },
  { id: 'l-116', unit: 'u5', lesson: 'u5-l1', type: 'fill', level: 'B1', category: 'Complete the sentence', question: "We expect to be back on _____ by next week.", options: ['track', 'the road', 'line'], answer: 0, explanation: '"Back on track" means returning to the planned schedule.', pt: '"Back ON track" é a expressão fixa para "voltar ao planejado" — "the road" e "line" não funcionam aqui.' },
  { id: 'l-117', unit: 'u5', lesson: 'u5-l1', type: 'translate', level: 'B1', category: 'Translation', question: 'Isso vai atrasar o lançamento em alguns dias.', accepted: ['This will delay the launch by a few days.', 'This will push back the launch by a few days.'], explanation: '"Delay [something] by [time]" or "push back [something] by [time]" are both natural.', pt: '"Delay/push back [algo] BY [tempo]" — repare que se usa "by", não "in" ou "for", para indicar de quanto algo atrasa.' },

  // u5-l2
  { id: 'l-118', unit: 'u5', lesson: 'u5-l2', type: 'mc', level: 'B2', category: 'Multiple Choice', question: 'You strongly disagree with a decision in writing. Most professional way to phrase it?', options: ['This is a bad idea.', "I have some concerns about this approach — could we discuss?", 'Whoever decided this was wrong.'], answer: 1, explanation: '"I have some concerns" opens dialogue instead of shutting it down with a blunt judgment.', pt: '"I have some concerns" abre espaço para diálogo, ao invés de fechar a conversa com um julgamento direto ("bad idea", "wrong").' },
  { id: 'l-119', unit: 'u5', lesson: 'u5-l2', type: 'fill', level: 'B2', category: 'Complete the sentence', question: "This decision could have serious _____ down the line.", options: ['consequences', 'results', 'endings'], answer: 0, explanation: '"Consequences down the line" is the natural way to talk about future impact.', pt: '"Consequences down the line" é a expressão natural para "consequências no futuro/mais pra frente" — "results" e "endings" não encaixam aqui.' },
  { id: 'l-120', unit: 'u5', lesson: 'u5-l2', type: 'reorder', level: 'B2', category: 'Reorder words', question: 'Put the words in order.', words: ['I', 'want', 'to', 'push', 'back', 'on', 'this', 'a', 'little.'], explanation: '"Push back on something" means to respectfully resist or question a decision.', pt: '"Push back ON something" é expressão idiomática para "questionar/resistir a algo" de forma respeitosa — não confundir com "push back" de adiar prazo.' },

  // u6-l1
  { id: 'l-121', unit: 'u6', lesson: 'u6-l1', type: 'mc', level: 'B1', category: 'Multiple Choice', question: 'How should you end your "Tell me about yourself" answer?', options: ['Just stop talking.', "That's what brings me here today, excited to learn more about this role.", 'That is all I have to say about my life.'], answer: 1, explanation: 'A natural closing connects your story back to why you\'re in the interview.', pt: 'Terminar a resposta conectando sua trajetória ao motivo da entrevista mostra intenção clara — parar abruptamente ou soar existencial ("about my life") quebra o tom profissional.' },
  { id: 'l-122', unit: 'u6', lesson: 'u6-l1', type: 'fill', level: 'B1', category: 'Complete the sentence', question: "I've spent the last three years _____ on backend systems.", options: ['working', 'work', 'to work'], answer: 0, explanation: '"Spend time + verb-ing" is the correct structure.', pt: '"Spend [tempo] + verbo em -ing" é a estrutura gramatical certa — não "to work", que soa como erro de tradução.' },
  { id: 'l-123', unit: 'u6', lesson: 'u6-l1', type: 'translate', level: 'B1', category: 'Translation', question: 'Atualmente eu trabalho como desenvolvedor em uma startup.', accepted: ['I currently work as a developer at a startup.', 'I currently work as a developer for a startup.'], explanation: '"Work as [role]" is the standard structure to describe your job.', pt: '"Work AS [cargo]" é a estrutura fixa — não "work like" ou "work of", erros comuns de tradução direta.' },

  // u6-l2
  { id: 'l-124', unit: 'u6', lesson: 'u6-l2', type: 'mc', level: 'B1', category: 'Multiple Choice', question: '"Why should we hire you?" — best kind of answer?', options: ['Because I need a job.', 'Connect your specific skills to what this role actually needs.', 'I don\'t know, you tell me.'], answer: 1, explanation: 'Interviewers want to hear how your specific strengths solve their specific problem.', pt: 'A resposta ideal conecta suas habilidades específicas às necessidades reais da vaga — respostas genéricas ou evasivas não convencem.' },
  { id: 'l-125', unit: 'u6', lesson: 'u6-l2', type: 'fill', level: 'B1', category: 'Complete the sentence', question: "My goal is to grow _____ a leadership role eventually.", options: ['into', 'to', 'for'], answer: 0, explanation: '"Grow into a role" is the natural collocation for career progression.', pt: '"Grow INTO a role" é a combinação natural para falar de crescimento de carreira — "to" e "for" não funcionam aqui.' },
  { id: 'l-126', unit: 'u6', lesson: 'u6-l2', type: 'reorder', level: 'B1', category: 'Reorder words', question: 'Put the words in order.', words: ['I', 'take', 'full', 'ownership', 'of', 'my', 'mistakes.'], explanation: '"Take ownership of" is a valued professional expression for accountability.', pt: '"Take ownership of [algo]" é expressão muito valorizada em entrevistas — mostra responsabilidade e maturidade profissional.' },

  // u7-l1
  { id: 'l-127', unit: 'u7', lesson: 'u7-l1', type: 'mc', level: 'A2', category: 'Multiple Choice', question: 'A user can\'t log in. Best first question?', options: ['Are you sure?', 'Can you confirm the exact error message you\'re getting?', 'Why not?'], answer: 1, explanation: 'A specific, concrete question speeds up diagnosis.', pt: 'Perguntas específicas e concretas ("the exact error message") aceleram o diagnóstico técnico — perguntas vagas ("Are you sure?", "Why not?") não ajudam.' },
  { id: 'l-128', unit: 'u7', lesson: 'u7-l1', type: 'fill', level: 'B1', category: 'Complete the sentence', question: "I'll go ahead and _____ a ticket for this.", options: ['open', 'make', 'do'], answer: 0, explanation: '"Open a ticket" is the standard collocation in support contexts.', pt: '"Open a ticket" é a combinação fixa para "abrir um chamado" — "make" e "do" não são usados nesse sentido técnico.' },
  { id: 'l-129', unit: 'u7', lesson: 'u7-l1', type: 'translate', level: 'A2', category: 'Translation', question: 'Você pode limpar o cache e tentar de novo?', accepted: ['Can you clear the cache and try again?', 'Could you clear the cache and try again?'], explanation: 'Common first-line troubleshooting instruction.', pt: 'Instrução clássica de primeiro nível de suporte — "clear the cache" é a expressão técnica padrão para "limpar o cache".' },

  // u7-l2
  { id: 'l-130', unit: 'u7', lesson: 'u7-l2', type: 'mc', level: 'B1', category: 'Multiple Choice', question: 'An incident has just been fully resolved. Natural closing message?', options: ['Fixed. Bye.', 'This incident has been fully resolved — thank you for your patience.', 'Problem gone now, ok.'], answer: 1, explanation: 'A formal, complete closing message is standard for incident communications.', pt: 'Mensagens de encerramento de incidente seguem um tom formal e completo, agradecendo a paciência dos usuários — respostas curtas demais soam despreparadas.' },
  { id: 'l-131', unit: 'u7', lesson: 'u7-l2', type: 'fill', level: 'B1', category: 'Complete the sentence', question: 'We are rolling _____ a fix within the next 30 minutes.', options: ['out', 'up', 'in'], answer: 0, explanation: '"Roll out a fix" is the standard phrasal verb for deploying a solution.', pt: '"Roll OUT a fix" é phrasal verb técnico padrão para "implantar uma correção" — só funciona com "out".' },
  { id: 'l-132', unit: 'u7', lesson: 'u7-l2', type: 'reorder', level: 'B1', category: 'Reorder words', question: 'Put the words in order.', words: ['We', 'apologize', 'for', 'any', 'inconvenience', 'caused.'], explanation: 'A standard formal apology line used in incident communications.', pt: 'Frase-padrão de comunicações de incidente — fórmula fixa, quase sempre usada exatamente assim em avisos oficiais.' },

  // u8-l1
  { id: 'l-133', unit: 'u8', lesson: 'u8-l1', type: 'mc', level: 'B2', category: 'Multiple Choice', question: 'You want to counter-propose during a negotiation. Natural opener?', options: ['No, that\'s wrong.', 'What if we approached it this way instead?', 'I refuse that.'], answer: 1, explanation: 'A question-based counter-proposal invites collaboration instead of confrontation.', pt: 'Propor uma contra-alternativa em forma de pergunta ("What if we...") convida à colaboração, em vez de confrontar diretamente ("No, that\'s wrong").' },
  { id: 'l-134', unit: 'u8', lesson: 'u8-l1', type: 'fill', level: 'B2', category: 'Complete the sentence', question: "That's a dealbreaker _____ us.", options: ['for', 'to', 'with'], answer: 0, explanation: '"A dealbreaker for [someone]" is the fixed structure.', pt: '"Dealbreaker FOR [alguém]" é estrutura fixa — significa algo que inviabiliza totalmente um acordo.' },
  { id: 'l-135', unit: 'u8', lesson: 'u8-l1', type: 'translate', level: 'B2', category: 'Translation', question: 'Vamos precisar renegociar o escopo do projeto.', accepted: ["We'll need to renegotiate the project scope.", 'We will need to renegotiate the scope of the project.'], explanation: 'Standard phrasing for reopening a negotiation.', pt: '"Renegotiate the scope" é a forma natural — "project scope" ou "scope of the project" são ambas corretas em inglês.' },

  // u8-l2
  { id: 'l-136', unit: 'u8', lesson: 'u8-l2', type: 'mc', level: 'B2', category: 'Multiple Choice', question: 'You want to invite questions at the end of a presentation. Natural phrasing?', options: ['Questions now, go.', "I'll pause here — happy to take any questions.", 'Ask me things if you have.'], answer: 1, explanation: 'A relaxed, inviting phrase encourages genuine audience participation.', pt: '"Happy to take any questions" convida a audiência de forma leve e natural — frases muito curtas ou mal construídas soam bruscas.' },
  { id: 'l-137', unit: 'u8', lesson: 'u8-l2', type: 'fill', level: 'B1', category: 'Complete the sentence', question: 'To sum _____, we delivered on time and under budget.', options: ['up', 'to', 'in'], answer: 0, explanation: '"To sum up" is the fixed phrase for concluding a presentation.', pt: '"To sum UP" é expressão fixa para "resumindo/para concluir" — usada para fechar apresentações.' },
  { id: 'l-138', unit: 'u8', lesson: 'u8-l2', type: 'reorder', level: 'B1', category: 'Reorder words', question: 'Put the words in order.', words: ['Feel', 'free', 'to', 'interrupt', 'me', 'at', 'any', 'time.'], explanation: 'A common, welcoming line to open the floor for questions during a talk.', pt: '"Feel free to..." é forma cordial de convidar interrupções/perguntas durante uma apresentação — soa acolhedor, não uma ordem.' },

  // u9-l1
  { id: 'l-139', unit: 'u9', lesson: 'u9-l1', type: 'mc', level: 'A2', category: 'Multiple Choice', question: 'Your flight is delayed. Best way to ask an airline staff member for information?', options: ['Flight late, why?', 'Excuse me, could you tell me what\'s happening with flight 205?', 'This is unacceptable, fix it now.'], answer: 1, explanation: 'A polite, specific question gets clearer information than a demand.', pt: 'Uma pergunta educada e específica ("Excuse me, could you tell me...") funciona muito melhor do que exigir uma resposta — mesmo estressado, vale manter a educação.' },
  { id: 'l-140', unit: 'u9', lesson: 'u9-l1', type: 'fill', level: 'A2', category: 'Complete the sentence', question: 'Could you recommend somewhere to eat _____ walking distance?', options: ['within', 'inside', 'on'], answer: 0, explanation: '"Within walking distance" is the fixed expression for "close enough to walk."', pt: '"Within walking distance" é expressão fixa para "perto o suficiente para ir a pé" — "inside" e "on" não funcionam aqui.' },
  { id: 'l-141', unit: 'u9', lesson: 'u9-l1', type: 'translate', level: 'A2', category: 'Translation', question: 'A que horas é o check-out?', accepted: ["What time is check-out?", 'What time is checkout?'], explanation: 'A basic, essential hotel question.', pt: 'Pergunta essencial em qualquer hotel — "check-out" já é usado universalmente, inclusive no português falado no Brasil.' },

  // u9-l2
  { id: 'l-142', unit: 'u9', lesson: 'u9-l2', type: 'mc', level: 'B1', category: 'Multiple Choice', question: 'You need to describe symptoms to a doctor abroad. Best approach?', options: ['Sick, help.', "I've had a fever and a headache since yesterday.", 'My body no good.'], answer: 1, explanation: 'Specific, complete sentences about symptoms and timing help doctors help you faster.', pt: 'Descrever sintomas de forma específica e completa (o quê + desde quando) ajuda o médico a te atender mais rápido — frases fragmentadas atrapalham o diagnóstico.' },
  { id: 'l-143', unit: 'u9', lesson: 'u9-l2', type: 'fill', level: 'A2', category: 'Complete the sentence', question: "I think I've been _____ my wallet.", options: ['robbed of', 'stolen', 'robbed from'], answer: 0, explanation: '"Robbed of [something]" is the correct passive structure.', pt: '"Robbed OF [algo]" é a estrutura passiva certa — "stolen" se usa para o objeto ("my wallet was stolen"), não para a pessoa.' },
  { id: 'l-144', unit: 'u9', lesson: 'u9-l2', type: 'reorder', level: 'A2', category: 'Reorder words', question: 'Put the words in order.', words: ['Could', 'you', 'call', 'an', 'ambulance,', 'please?'], explanation: 'A clear, polite way to request emergency medical help.', pt: 'Pedido claro e educado de ajuda médica de emergência — mesmo em situação urgente, "please" mantém a frase natural em inglês.' }
];
